const adminTopTags = `-- name: AdminTopTags :many
SELECT t.slug, t.name, count(pt.post_id)::bigint AS post_count
FROM tags t
JOIN post_tags pt ON pt.tag_id = t.id
JOIN posts p ON p.id = pt.post_id
WHERE p.deleted_at IS NULL AND p.visibility = 'public'
GROUP BY t.id, t.slug, t.name
ORDER BY post_count DESC, t.name
LIMIT $1::int
`

type AdminTopTagsRow struct {
	Slug      string `json:"slug"`
	Name      string `json:"name"`
	PostCount int64  `json:"post_count"`
}

// 话题热度榜：按公开帖子数排序，给运营看社区关注点。
func (q *Queries) AdminTopTags(ctx context.Context, limitCount int32) ([]AdminTopTagsRow, error) {
	rows, err := q.db.Query(ctx, adminTopTags, limitCount)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []AdminTopTagsRow
	for rows.Next() {
		var i AdminTopTagsRow
		if err := rows.Scan(&i.Slug, &i.Name, &i.PostCount); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
